// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public {
        c = new Roulette();
    }

    function testFuzz_payoutIndependentOfTimestamp(address actor, uint256 ts, uint256 bn) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(uint160(actor) > 9);
        vm.assume(actor.code.length == 0);

        uint256 timestamp = bound(ts, 1, type(uint64).max);
        uint256 bnum = bound(bn, 1, type(uint64).max);
        vm.warp(timestamp);
        vm.roll(bnum);

        vm.deal(address(c), 100 ether);
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        if (ok && (bnum % 15 != 0)) {
            assertEq(address(c).balance, 110 ether);
        }
    }
}
